def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    op_c = 0
    for _, o in history:
        if o == 'C':
            op_c += 1
    if op_c == 0:
        return 'D'

    my_last, op_last = history[-1]

    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    if streak >= 2:
        if my_last == 'D':
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
